 '1-06':{title:'格雷码编码',stem:'采用3位标准反射格雷码对整数0～7编码，其中十进制数5对应111。十进制数6对应的码字为（ ）。',options:['100','101','110','111'],answer:1,explanation:'6的自然二进制码为110，标准反射格雷码等于该二进制码与其右移一位的结果异或：110⊕011＝101。也可按反射构造顺序查得；不能把自然二进制码110直接当作格雷码。'},
 '2-02':{title:'复合逻辑运算',stem:'逻辑表达式F＝A⊕B⊕B的结果为（ ）。',options:['A','A′','B','A⊙B'],answer:0,explanation:'异或满足结合律，B⊕B＝0，故F＝A⊕0＝A。不能把两个相同的异或项按逻辑或的幂等律处理。'},
 '2-03':{title:'逻辑表达式变换',stem:'与逻辑表达式F＝(A＋B′C)′等价的是（ ）。',options:['A′(B＋C′)','A′＋BC′','A′(B′＋C)','A′BC′'],answer:0,explanation:'先对外层用德摩根定律：F＝A′(B′C)′；再对乘积取反，得A′(B＋C′)。反演时必须同时改变运算关系与各项的极性。'},
 '2-04':{title:'逻辑函数化简',stem:'函数F＝A′B＋AB＋B′C的最简与或式为（ ）。',options:['B','C','B＋C','A＋C'],answer:2,explanation:'A′B＋AB＝B(A′＋A)＝B；再由B＋B′C＝B＋C，得到F＝B＋C。仅合并前两项会漏掉B＝0、C＝1时的输出。'},
 '2-05':{title:'逻辑代数规则',stem:'表达式F＝A(B＋0)的对偶式为（ ）。',options:['A＋B·1','A′＋B′·1','A(B＋1)','A＋B·0'],answer:0,explanation:'构造对偶式时交换逻辑与、逻辑或，并交换常量0、1；变量不取反，故得A＋B·1。对偶式不是反函数。'},
 '2-06':{title:'标准形式转换',topic:'最小项与最大项',stem:'设三变量函数F(A,B,C)＝Σm(1,2,6)，变量按ABC排列，A为最高位。F的最大项表达式为（ ）。',options:['ΠM(0,3,4,5,7)','ΠM(1,2,6)','ΠM(0,1,3,4,5,7)','ΠM(3,4,5,7)'],answer:0,explanation:'最小项展开列出F＝1的编号，最大项展开列出F＝0的编号。三变量编号为0～7，去掉1、2、6，得到0、3、4、5、7。'},
 '2-07':{title:'卡诺图合并',stem:'四变量函数F(A,B,C,D)＝Σm(0,2,8,10)，A为最高位。用卡诺图化简所得的最简与或式为（ ）。',options:['A′C′','B′D′','B′C′','A′D′'],answer:1,explanation:'四个最小项为0000、0010、1000、1010。它们的B、D均为0，A、C遍历全部组合，故合并得B′D′。格雷顺序卡诺图可利用首尾相邻进行合并。'},
