  "P4-digital-1-F-015": {
    "2": {
      "stem": "采用3位标准反射格雷码对位置0～7编码，码字001与101对应的位置编号分别为____、____。这两个码字只差一位，是否就能说明位置编号相邻？____（能/不能）。",
      "answers": [
        [
          "1"
        ],
        [
          "6"
        ],
        [
          "不能"
        ]
      ],
      "formats": [
        "number",
        "number",
        "text"
      ],
      "explanation": "按累计异或还原，001对应二进制001，即位置1；101对应二进制110，即位置6。两个格雷码只差最高位，位置编号却相差5，因此不能据“码字只差一位”反推位置相邻。标准反射格雷码保证相邻位置的码字只变一位，这个性质的逆命题并不成立。"
    }
  },
  "P4-digital-1-F-017": {
    "2": {
      "stem": "两组四位数据分别配有偶校验位PA、PB。现只拼接两组原始数据，不包含原来的校验位，再添加一个总偶校验位P。用PA、PB表示，P=____。",
      "answers": [
        [
          "PA⊕PB",
          "PB⊕PA",
          "PA^PB",
          "PB^PA",
          "PA XOR PB",
          "PB XOR PA"
        ]
      ],
      "formats": [
        "text"
      ],
      "explanation": "PA等于第一组四位数据的异或，PB等于第二组四位数据的异或。八位原始数据拼接后的总异或就是PA⊕PB，所以总偶校验位P=PA⊕PB。比如PA=PB=1时，两组各含奇数个1，合起来是偶数个1，应取P=0，不能把两个校验位简单作逻辑或。若把原校验位也一同拼接，则是另一种问题；本题已明确不包含它们。"
    }
  },
