      "stem": "二进制伙伴池总长2^M，q是正的总块长需求。每阶空闲集合支持常数时间判空，并能在期望摊还O(1)内取出任意块或插入块。请设计分配步骤：优先找最小可用阶，拆分时继续用低地址半块。说明时间量级。",
