export function practiceQuestionAtRevision(source,revision,versions=practiceQuestionRevisions[source.id]){
 if(!versions)return source;
 const baseline=source.revision??1,wanted=revision??Math.max(baseline,...Object.keys(versions).map(Number));
 if(!Number.isInteger(wanted))throw Error('题目版本不受支持，请保留原备份。');
 if(wanted===baseline)return source;
 const patch=versions[wanted];if(!patch)throw Error('题目版本不受支持，请保留原备份。');
 return {...source,...patch,revision:wanted};
}
